"""Static UI; local-token auth and textContent for all untrusted content."""
HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>欺诈告警调查</title>
<style>*{box-sizing:border-box}body{font:16px/1.65 system-ui;margin:0;background:#eef3f4;color:#17343e}main{max-width:1100px;margin:auto;padding:24px}section{background:white;padding:24px;border-radius:12px;margin:18px 0}label{display:block;margin:12px 0}input,select,textarea{display:block;width:100%;padding:10px;font:inherit;border:1px solid #b7c9cc;border-radius:6px}button{padding:10px 16px;margin:5px;font:inherit;border:0;border-radius:6px;background:#14695d;color:white;cursor:pointer}button:disabled{opacity:.45;cursor:default}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f6f8;padding:12px}#error{color:#9e2222}a{color:#14695d}</style>
<main><h1>欺诈告警调查</h1><p>检测告警 → 历史行为证据 → 人工审阅。源数据为 IBM 合成交易；当前新任务使用确定性接线客户端，不代表真实模型调查效果。</p><a href="/">返回原工作台</a><section><label>本地访问令牌<input id="token" type="password"></label><details><summary>历史支付差错实验（非欺诈主线）</summary><label>案例<select id="case"><option value="case-03">商户业务变化</option><option value="case-04">证据冲突</option><option value="case-01">重复授权</option><option value="case-06">历史资料不足</option></select></label><label>调查目标<textarea id="goal">Investigate merchant change</textarea></label><button id="start">开始调查</button></details><button id="refresh">刷新任务列表</button><div id="jobs"></div><p id="error"></p></section>
<section><h2>绑定检测告警</h2><p id="fraud-source">使用本地令牌刷新后加载已注册的神经模型告警；不会自动替换成手写案卷。</p><select id="fraud-case"></select><button id="fraud-refresh">加载检测告警</button><button id="fraud-start" disabled>核查该告警的历史行为</button></section><section><h2 id="state">尚未选择任务</h2><p id="mode"></p><pre id="answer"></pre><h3>技能与进度</h3><pre id="progress"></pre><details><summary>取证原文和运行事件</summary><pre id="evidence"></pre></details></section>
<section><h2>待审阅工单</h2><p>核对报告后保存草稿，再批准当前内容。修改草稿会使旧批准失效。提交目的地是本机模拟队列，没有资金或账户操作。</p><textarea id="draft" placeholder="说明待人工处理的事项"></textarea><button id="save" disabled>保存草稿</button><button id="approve" disabled>批准当前草稿</button><button id="send" disabled>提交模拟工单</button><pre id="receipt"></pre></section>
<section id="fraud-memory-panel"><h2>欺诈审阅记忆</h2><p>记录已审阅的行为线索和下次核查重点。候选须检查来源并批准，后续任务只读取同一用户、已发生且当时可用的记录。它不证明授权或欺诈，也不替代重新取证。</p><pre id="fm-snapshot">选择欺诈调查任务后查看。</pre><label>后续核查重点<select id="fm-focus"><option value="authorization">补充持卡人授权证据</option><option value="coverage">优先确认历史资料覆盖</option><option value="merchant_context">补充商户背景证据</option><option value="none">按当前证据继续核查</option></select></label><button id="fm-create" disabled>生成审阅记忆候选</button><button id="fm-assess" disabled>检查来源与范围</button><pre id="fm-candidate">尚未生成候选</pre><div id="fm-checks"></div><button id="fm-publish" disabled>批准并发布当前候选</button><button id="fm-refresh">刷新可复用记录</button><pre id="fm-head"></pre><label>已发布记录<select id="fm-active"></select></label><button id="fm-withdraw" disabled>撤下选中记录</button><p>撤下影响之后的新任务；已冻结任务和审计记录保留。这不是物理删除，也不会改变检测规则。</p><p id="fm-error" role="status"></p></section>
<details id="legacy-methods"><summary>展开历史支付差错研究组件（非欺诈主线）</summary><section><h2>历史差错实验：过程知识与经验版本</h2><p>此处的清算与商户解释方法不适用于欺诈告警；系统拒绝从欺诈任务发布这类经验。</p><p>调查任务固定提交时的规程和经验版本。D 段落与 M 经验只指导调查，不能替代 E 案件证据。检索使用本地 BM25；神经检索对照见阶段报告。</p><pre id="knowledge"></pre><button id="methods-refresh">刷新经验版本</button><pre id="method-head"></pre><label>候选调查顺序<select id="method-order"><option value="coverage,settlement,merchant">历史覆盖 → 清算 → 商户解释</option><option value="merchant,settlement,coverage">商户解释 → 清算 → 历史覆盖（用于检验错误经验）</option><option value="settlement,coverage,merchant">清算 → 历史覆盖 → 商户解释</option></select></label><p>以当前已结束的调查作为审阅来源。候选只生成通用方法，不复制案件事实；修改会创建新修订并重新验证。</p><button id="method-create">创建候选修订</button><button id="method-evaluate" disabled>运行任务回归</button><button id="method-publish" disabled>审阅并发布当前修订</button><pre id="method-candidate"></pre><label>回滚到版本（0 表示撤下所有经验）<input id="rollback-target" type="number" min="0" value="0"></label><button id="method-rollback">确认回滚</button><p id="method-error" role="status"></p></section></details></main>
<script>
const $=id=>document.getElementById(id);let current=null,ticket=null,timer=null,submitKey=null,draftDirty=false,shown=null;const states={queued:'等待处理',running:'调查中',awaiting_review:'报告等待审阅',blocked:'已阻塞',failed:'调查失败',cancelled:'已取消'};
$('token').value=sessionStorage.getItem('riskcase-local-token')||'';
async function api(url,body,key){let r=await fetch(url,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+$('token').value,'Content-Type':'application/json',...(key?{'Idempotency-Key':key}:{})},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error('请求失败 '+r.status);return r.json()}
function error(e){$('error').textContent=e.message}
function answerView(result){
 if(!result)return '等待结果';
 const a=result.answer;
 if(a.findings){const v=result.validation,labels={high_prior_frequency_1h:'此前一小时至少4笔交易',amount_above_prior_positive_max_30d:'本笔正金额超过30天历史最大值',merchant_id_unseen_30d:'30天历史未见该商户'},states={supported:'支持该线索',not_supported:'不支持该线索',insufficient_evidence:'资料不足'};
 const lines=['建议：'+(a.verdict==='request_records'?'先补证据，再人工审核':'提交分析师审核；不认定欺诈或安全'),'检测分数：'+v.alert.alert.score.toFixed(4)+'（未校准排序分数）','源交易：'+v.alert.transaction.transaction_id,'调查事实截止：'+v.alert.transaction.event_time,'日终名单可得时间：'+v.queue_available_at,'统计范围：同一用户的历史交易；非单卡口径。金额单位为源最小单位，币种未知。'];
 for(const f of a.findings){lines.push('\n'+labels[f.check]+'：'+states[f.assessment]);for(const ref of f.evidence_ids){const e=v.evidence[ref];if(!e)continue;if(e.tool==='summarize_history')lines.push('['+ref+'] 前'+e.lookback_hours+'小时 '+e.prior_count+' 笔；本笔金额 '+e.target_amount_cents+'；历史正金额最大值 '+(e.positive_amount_max_cents??'无可比较样本')+'；源内覆盖'+(e.complete_within_source?'完整':'不足'));if(e.tool==='query_target_merchant')lines.push('['+ref+'] 前30天用户历史 '+e.prior_count+' 笔，该商户出现 '+e.merchant_prior_count+' 笔；源内覆盖'+(e.complete_within_source?'完整':'不足'));}}
 lines.push('\n缺失材料：持卡人授权确认、设备与认证记录、外部结案结果。','这些行为线索不能证明持卡人授权或欺诈；全不支持也不自动关闭告警。','完整字段、源行预览和指纹可在下方取证记录展开查看。');return lines.join('\n');}

 if(!a.claims)return '结论：'+({normal_change:'业务变化得到佐证',duplicate_record:'重复记录线索',needs_review:'需要人工进一步调查',insufficient_evidence:'资料不足'}[a.verdict]||a.verdict)+'\n引用：'+a.evidence_ids.join('、')+'\n待补材料：'+(a.missing.join('；')||'无已声明缺口');
 const labels={settled_debits:'已观察入账扣款笔数',net_debit_cents:'已观察净扣款（人民币分）',reversal_state:'退款状态',coverage:'清算覆盖'};
 const actions={close_explained:'差异已得到解释，待人工确认',escalate_duplicate:'需升级调查重复入账',await_reversal:'等待并核对退款入账',request_records:'先补充缺失资料'};let lines=['建议：'+(actions[a.verdict]||a.verdict),'引用已检查；事实含义、计算和规程适用仍须人工逐项复核。'];
 for(const claim of result.validation.claims){lines.push('\n'+labels[claim.name]+'：'+claim.value);for(const src of claim.sources)lines.push(src.document_id+'\n'+src.lines.map(l=>'L'+l.number+' '+l.text).join('\n'));}
 lines.push('\n适用规程：'+result.validation.policy.document_id,...result.validation.policy.lines.map(l=>'L'+l.number+' '+l.text),'\n待补资料：'+(a.missing.join('、')||'未声明'));
 return lines.join('\n');
}
function progressView(row,c){
 if(!c)return '等待检查点';
 const common='已加载技能：'+Object.keys(c.skills).join('、')+'\n阶段：'+c.phase+'；交互轮次：'+c.turn+'；工具尝试：'+c.attempts;
 if(row.result?.answer?.claims||c.proposed_answer?.claims||row.result?.answer?.findings||c.proposed_answer?.findings){const a=row.result?.answer||c.proposed_answer;return common+'\n本流程使用结构化主张与原文核查，不使用自由文本待办。\n报告待补材料：'+(a.missing.join('；')||'未声明；仍需逐项人工审阅');}
 return common+'\n待办：'+(c.plan.todo.join('；')||'已完成')+'\n仍需确认：'+(c.plan.unknowns.join('；')||'无已声明缺口');
}
function renderSemanticReview(result){
 let box=$('semantic-review');const fraud=result?.validation?.contract==='detector-fraud-review-v1';const kind=fraud?'fraud':'dossier';
 if(!box){box=document.createElement('div');box.id='semantic-review';$('draft').before(box);}
 if(box.dataset.kind!==kind){box.replaceChildren();box.dataset.kind=kind;const labels=fraud?{findings:'行为线索与源内统计',scope:'分数、时间与非欺诈结论边界',missing:'授权和外部结案缺口'}:{settled_debits:'扣款笔数',net_debit_cents:'净额计算',reversal_state:'退款状态',coverage:'覆盖范围',policy:'规程适用',missing:'缺失资料'};for(const [value,label] of Object.entries(labels)){let lab=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.className='semantic-check';input.value=value;input.style.cssText='display:inline;width:auto;margin-right:8px';lab.append(input,document.createTextNode('已核对'+label));box.append(lab);}}
 box.hidden=result?.validation?.semantic_validation!==false;
}
async function fraudCatalog(){const data=await api('/fraud-alerts');$('fraud-case').replaceChildren();for(const row of data.alerts){const o=document.createElement('option');o.value=row.case_id;o.textContent=row.case_id+' · 排名 '+row.alert.day_rank+' · '+row.cutoff;$('fraud-case').append(o);}$('fraud-start').disabled=!data.alerts.length;$('fraud-source').textContent=data.alerts.length?'已加载 '+data.alerts.length+' 个检测告警；IBM 合成源，确定性客户端经真实 MCP 核查。':'当前目录没有可验证的神经模型告警。请按主线指南加载源数据 catalog；历史实验不能替代它。';}
$('fraud-refresh').onclick=()=>fraudCatalog().catch(error);
$('fraud-start').onclick=async()=>{try{submitKey=submitKey||'fraud-'+crypto.randomUUID();const row=await api('/fraud-investigations',{case_id:$('fraud-case').value,text:'核查检测告警的三项历史行为线索，保留授权与外部结案缺口。'},submitKey);submitKey=null;current=row.id;await refresh();if(!timer)timer=setInterval(()=>refresh().catch(error),2000)}catch(e){error(e)}};

async function refresh(){const rows=(await api('/investigations')).jobs;$('jobs').replaceChildren();for(const row of rows){let b=document.createElement('button');b.textContent=row.case_id+' · '+(states[row.state]||row.state);b.onclick=()=>select(row.id).catch(error);$('jobs').append(b)}if(current)await select(current)}
async function select(id){if(shown!==id){shown=id;draftDirty=false;resetMemoryCandidate();$('draft').value='';document.querySelectorAll('.semantic-check').forEach(x=>x.checked=false)}current=id;const row=await api('/investigations/'+id);if(current!==id)return;$('state').textContent=states[row.state]||row.state;$('mode').textContent=(row.result?.client_kind==='configured_external_client'?'外部模型调用或回放记录':row.result?.client_kind==='simulation'?'确定性控制或模拟客户端记录':!row.result&&row.execution_mode==='live'?'外部模型任务：工作台仅展示，不自动运行':'历史或待运行记录，请结合调用回执核对')+'；恢复代次 '+row.generation+(row.reason?'；停止原因 '+row.reason:'');$('answer').textContent=answerView(row.result);renderSemanticReview(row.result);const c=row.checkpoint;$('progress').textContent=progressView(row,c);$('evidence').textContent=JSON.stringify({context:c?.context_metrics,evidence:c?.evidence,draft_reviews:c?.draft_reviews,events:row.events},null,2);if(row.result?.review_warnings?.length)$('answer').textContent+=row.result?.validation?.semantic_validation===false?'\n批准前必须逐项核对事实、规程与缺失资料。':'\n注意：调查计划仍有待复核事项，请在批准工单前核对。';renderMemory(row);ticket=row.ticket;if(!draftDirty&&ticket)$('draft').value=ticket.payload.text;$('save').disabled=row.state!=='awaiting_review'||ticket?.status==='submitted'||ticket?.status==='uncertain';$('approve').disabled=draftDirty||!ticket||ticket.approved_hash===ticket.hash||ticket.status!=='draft';$('send').disabled=draftDirty||!ticket||ticket.approved_hash!==ticket.hash;$('receipt').dataset.ticketId=ticket?.receipt?.id||'';$('receipt').dataset.status=ticket?.status||'none';$('receipt').textContent=ticket?(ticket.status==='submitted'?'已提交至本地模拟队列\n工单编号：'+ticket.receipt.id:ticket.status==='uncertain'?'提交结果待核对；再次提交会先按幂等键查询。':ticket.approved_hash===ticket.hash?'当前草稿已批准，可提交至本地模拟队列。':'草稿已保存，等待批准当前内容。'):'尚未保存草稿'}
$('start').onclick=async()=>{try{submitKey=submitKey||'ui-'+crypto.randomUUID();const row=await api('/investigations',{case_id:$('case').value,text:$('goal').value},submitKey);submitKey=null;current=row.id;await refresh();if(!timer)timer=setInterval(()=>refresh().catch(error),2000)}catch(e){error(e)}};
$('refresh').onclick=()=>refresh().catch(error);
$('draft').oninput=()=>{draftDirty=true;$('approve').disabled=true;$('send').disabled=true};
$('save').onclick=async()=>{try{await api('/investigations/'+current+'/draft',{text:$('draft').value,expected_hash:ticket?.hash||null});draftDirty=false;await select(current)}catch(e){error(e)}};
$('approve').onclick=async()=>{try{await api('/investigations/'+current+'/approve',{expected_hash:ticket.hash,reviewed_claims:[...document.querySelectorAll('.semantic-check:checked')].map(x=>x.value)});await select(current)}catch(e){error(e)}};
$('send').onclick=async()=>{try{await api('/investigations/'+current+'/submit-ticket',{expected_hash:ticket.hash});await select(current)}catch(e){error(e)}};
if($('token').value)refresh().catch(error);
let methodHead=null,methodCandidate=null;
function methodError(e){$('method-error').textContent=e.message}
function renderCandidate(){const c=methodCandidate;$('method-candidate').textContent=c?c.content.text+'\n修订：'+c.id+'\n任务回归：'+(c.evaluation?(c.evaluation.passed?'通过':'拒绝')+'（'+c.evaluation.cases.filter(x=>x.correct).length+'/'+c.evaluation.cases.length+'）':'尚未运行'):'尚未选择候选';$('method-evaluate').disabled=!c;$('method-publish').disabled=!c?.evaluation?.passed}
async function refreshMethods(){const data=await api('/methods');methodHead=data.head;$('method-head').textContent='当前版本：'+methodHead.id+'\n'+(methodHead.lesson?methodHead.lesson.text:'没有已发布经验')+'\n最近版本：'+data.releases.map(x=>x.id+' '+x.action).join('；');if(current){const row=await api('/investigations/'+current);$('knowledge').textContent='当前任务固定经验版本：'+row.knowledge_snapshot.release+'\n知识快照：'+row.knowledge_snapshot.hash+'\n'+(row.checkpoint?.observations||[]).filter(x=>x.kind==='knowledge').flatMap(x=>[...x.retrieval.hits,...x.memory.hits]).map(x=>x.citation+'\n'+x.text).join('\n\n')}}
$('method-order').onchange=()=>{$('method-publish').disabled=true;$('method-evaluate').disabled=true;$('method-error').textContent='顺序已修改，请创建新修订后重新验证。'};
$('methods-refresh').onclick=()=>refreshMethods().catch(methodError);
$('method-create').onclick=async()=>{try{if(!current)throw Error('先选择一个已结束的调查');methodCandidate=await api('/methods/candidates',{source_job:current,order:$('method-order').value.split(','),parent:methodCandidate?.id||null});renderCandidate();await refreshMethods()}catch(e){methodError(e)}};
$('method-evaluate').onclick=async()=>{try{methodCandidate=await api('/methods/candidates/'+methodCandidate.id+'/evaluate',{});renderCandidate()}catch(e){methodError(e)}};
$('method-publish').onclick=async()=>{try{await api('/methods/candidates/'+methodCandidate.id+'/publish',{expected_hash:methodCandidate.hash,expected_head:methodHead.hash});methodCandidate=null;renderCandidate();await refreshMethods();$('method-error').textContent='已发布；仅之后提交的新任务采用此版本。'}catch(e){methodError(e)}};
$('method-rollback').onclick=async()=>{try{if(!methodHead)await refreshMethods();await api('/methods/rollback',{target:Number($('rollback-target').value),expected_head:methodHead.hash});await refreshMethods();$('method-error').textContent='已回滚；已有任务保留原知识快照。'}catch(e){methodError(e)}};
if($('token').value)refreshMethods().catch(methodError);

let memoryCandidate=null,memoryHead=null,memoryRow=null;
const focusLabels={authorization:'补充持卡人授权证据',coverage:'优先确认历史资料覆盖',merchant_context:'补充商户背景证据',none:'按当前证据继续核查'};
function memoryError(e){$('fm-error').textContent=e.message}
function resetMemoryCandidate(){memoryCandidate=null;$('fm-assess').disabled=true;$('fm-publish').disabled=true;$('fm-candidate').textContent='尚未生成候选';document.querySelectorAll('.fm-check').forEach(x=>x.checked=false)}
function renderMemory(row){memoryRow=row;const m=row.review_memory_snapshot,valid=row.result?.validation?.contract==='detector-fraud-review-v1';$('fm-create').disabled=!valid||row.state!=='awaiting_review';$('fm-snapshot').textContent=m?'本任务固定记忆版本：'+m.release+'；可复用记录 '+m.records.length+' 条。\n'+m.records.map(r=>r.body.case_id+' · '+focusLabels[r.body.focus]+'\n历史事实截止：'+r.body.event_cutoff+'\n审阅记录可得时间：'+new Date(r.recorded_at*1000).toISOString()+'\n仍缺：授权确认、设备认证、外部结案').join('\n\n'):'此任务不使用欺诈审阅记忆。';}
for(const [value,label] of Object.entries({source:'已核对来源报告',scope:'已核对主体和时间范围',advisory_only:'确认仅作调查提示，不是结案事实'})){const lab=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=value;box.className='fm-check';box.style.cssText='display:inline;width:auto;margin-right:8px';lab.append(box,document.createTextNode(label));$('fm-checks').append(lab);}
async function refreshMemory(){memoryHead=await api('/fraud-memory');$('fm-head').textContent='当前版本：'+memoryHead.release+'；有效登记 '+(memoryHead.active_count??0)+' 条（展示最近100条；过期或来源批准失效时，新任务不再召回）。';$('fm-active').replaceChildren();for(const r of memoryHead.previews){const o=document.createElement('option');o.value=r.candidate;o.textContent=r.case_id+' · '+focusLabels[r.focus];$('fm-active').append(o);}$('fm-withdraw').disabled=!memoryHead.records.length;}
$('fm-focus').onchange=resetMemoryCandidate;
$('fm-create').onclick=async()=>{try{if(!memoryRow?.report_hash)throw Error('先选择已完成的欺诈调查');resetMemoryCandidate();memoryCandidate=await api('/fraud-memory/candidates',{source_job:current,expected_report_hash:memoryRow.report_hash,focus:$('fm-focus').value});$('fm-candidate').textContent='来源：'+memoryCandidate.body.case_id+'\n核查重点：'+focusLabels[memoryCandidate.body.focus]+'\n仍缺授权、认证和结案证据；不会自动修改检测规则。\n候选：'+memoryCandidate.id;$('fm-assess').disabled=false;await refreshMemory()}catch(e){memoryError(e)}};
$('fm-assess').onclick=async()=>{try{const r=await api('/fraud-memory/candidates/'+memoryCandidate.id+'/assess',{expected_hash:memoryCandidate.hash});$('fm-candidate').textContent+='\n来源与范围检查通过；尚不代表业务效果。';$('fm-publish').disabled=!r.source_checks_passed}catch(e){memoryError(e)}};
$('fm-publish').onclick=async()=>{try{const reviewed=[...document.querySelectorAll('.fm-check:checked')].map(x=>x.value);await api('/fraud-memory/candidates/'+memoryCandidate.id+'/publish',{expected_hash:memoryCandidate.hash,expected_head:memoryHead.head,reviewed_claims:reviewed});await refreshMemory();$('fm-error').textContent='已发布，之后的新任务可按范围读取。当前任务保留原快照。'}catch(e){memoryError(e)}};
$('fm-refresh').onclick=()=>refreshMemory().catch(memoryError);
$('fm-withdraw').onclick=async()=>{try{await api('/fraud-memory/candidates/'+$('fm-active').value+'/withdraw',{expected_head:memoryHead.head});await refreshMemory();$('fm-error').textContent='已撤下；新任务不再召回。已有快照与审计记录保留。'}catch(e){memoryError(e)}};
</script></html>'''
